content.content:
.bp3-tab-copy {
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  word-wrap: normal;
  color: #182026;
  cursor: pointer;
  -webkit-box-flex: 0;
  -ms-flex: 0 0 auto;
  flex: 0 0 auto;
  font-size: 14px;
  line-height: 30px;
  max-width: 100%;
  position: relative;
  vertical-align: top;

  border-radius: 3px;
  padding: 0 10px;
  width: 100%;
}
.dg-settings-node-page {
  display: flex;
  flex-direction: column;
  gap: 44px;
  padding: 2px;
}

/** No row dividers: the only rule on a page is the one under a section heading. */

/* Translucent neutral so the badge reads on Roam's light and dark themes;
   the label and icon inherit the host foreground rather than a fixed palette. */
.dg-setting-row__scope {
  background-color: rgba(138, 155, 168, 0.15);
  border: 1px solid rgba(138, 155, 168, 0.25);
}

/* Trailing keycap control: a narrow box whose value reads as a single key. */
.dg-setting-keycap .bp3-input {
  text-align: center;
  font-family: monospace;
}
